"use client";

import React, { useState, useCallback } from "react";
import { cn } from "@/lib/utils";

interface Ripple {
  id: number;
  x: number;
  y: number;
  size: number;
}

interface RippleButtonProps {
  children: React.ReactNode;
  className?: string;
  rippleColor?: string;
  onClick?: () => void;
  disabled?: boolean;
}

let rippleId = 0;

export function RippleButton({
  children,
  className,
  rippleColor = "rgba(255,255,255,0.3)",
  onClick,
  disabled = false,
}: RippleButtonProps) {
  const [ripples, setRipples] = useState<Ripple[]>([]);

  const handleClick = useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      if (disabled) return;
      const rect = e.currentTarget.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const size = Math.max(rect.width, rect.height) * 2;
      const id = ++rippleId;
      setRipples((prev) => [...prev, { id, x, y, size }]);
      onClick?.();
    },
    [disabled, onClick]
  );

  const removeRipple = useCallback((id: number) => {
    setRipples((prev) => prev.filter((r) => r.id !== id));
  }, []);

  return (
    <button
      disabled={disabled}
      aria-disabled={disabled}
      onClick={handleClick}
      className={cn(
        "relative overflow-hidden px-8 py-4 text-sm font-semibold rounded-xl",
        "bg-zinc-900 text-white border border-white/[0.08]",
        "transition-all duration-300",
        "hover:border-white/[0.15] hover:shadow-[0_0_30px_rgba(255,255,255,0.08)]",
        "active:scale-[0.98]",
        "disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:border-white/[0.08] disabled:hover:shadow-none",
        className
      )}
    >
      {ripples.map((ripple) => (
        <span
          key={ripple.id}
          className="absolute rounded-full animate-[ripple-expand_600ms_ease-out_forwards] pointer-events-none"
          style={{
            left: ripple.x - ripple.size / 2,
            top: ripple.y - ripple.size / 2,
            width: ripple.size,
            height: ripple.size,
            backgroundColor: rippleColor,
          }}
          onAnimationEnd={() => removeRipple(ripple.id)}
        />
      ))}
      <span className="relative z-10">{children}</span>
    </button>
  );
}

/*
 * FlexUI Animations
 * Custom CSS keyframes and utility classes required by FlexUI components.
 * This file is auto-installed when you add a component that needs CSS animations.
 */

/* Marquee */
@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
@keyframes marquee-reverse {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}
@keyframes marquee-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}
@utility animate-marquee {
  animation: marquee 30s linear infinite;
}
@utility animate-marquee-reverse {
  animation: marquee-reverse 30s linear infinite;
}

/* Shimmer */
@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}
@utility animate-shimmer {
  animation: shimmer 2s linear infinite;
}

/* Typewriter cursor blink */
@keyframes typewriter-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

/* Gradient text shift */
@keyframes gradient-shift {
  0% { background-position: 0% center; }
  100% { background-position: 200% center; }
}
@utility animate-gradient-shift {
  animation: gradient-shift 3s linear infinite;
}

/* Beam sweep */
@keyframes beam-sweep {
  0% { transform: translateX(-100%) rotate(var(--tw-rotate, 0deg)); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateX(200%) rotate(var(--tw-rotate, 0deg)); opacity: 0; }
}
@utility animate-beam-sweep {
  animation: beam-sweep 8s linear infinite;
}

/* Star twinkle */
@keyframes star-twinkle {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 1; }
}
@utility animate-star-twinkle {
  animation: star-twinkle 3s ease-in-out infinite;
}

/* Mesh gradient blobs */
@keyframes mesh-blob-1 {
  0% { transform: translate(-50%, -50%) translate(0, 0); }
  100% { transform: translate(-50%, -50%) translate(80px, 60px); }
}
@keyframes mesh-blob-2 {
  0% { transform: translate(-50%, -50%) translate(0, 0); }
  100% { transform: translate(-50%, -50%) translate(-60px, 80px); }
}
@keyframes mesh-blob-3 {
  0% { transform: translate(-50%, -50%) translate(0, 0); }
  100% { transform: translate(-50%, -50%) translate(70px, -50px); }
}
@keyframes mesh-blob-4 {
  0% { transform: translate(-50%, -50%) translate(0, 0); }
  100% { transform: translate(-50%, -50%) translate(-50px, -70px); }
}

/* Wavy background drift */
@keyframes wave-drift {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* Aurora background shift */
@keyframes aurora-shift {
  0% { transform: translate(0%, 0%) rotate(0deg) scale(1); }
  25% { transform: translate(10%, -15%) rotate(5deg) scale(1.05); }
  50% { transform: translate(-5%, 10%) rotate(-3deg) scale(0.95); }
  75% { transform: translate(-10%, -5%) rotate(4deg) scale(1.02); }
  100% { transform: translate(0%, 0%) rotate(0deg) scale(1); }
}
@utility animate-aurora-shift {
  animation: aurora-shift 8s ease-in-out infinite;
}

/* Particle drift */
@keyframes particle-drift {
  0% { transform: translateY(0px) translateX(0px); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateY(-60px) translateX(20px); opacity: 0; }
}
@utility animate-particle-drift {
  animation: particle-drift 6s ease-in-out infinite;
}

/* Glow button pulse */
@keyframes glow-pulse {
  0%, 100% { box-shadow: 0 0 20px var(--glow-color), 0 0 60px var(--glow-color-soft); }
  50% { box-shadow: 0 0 30px var(--glow-color-intense), 0 0 80px var(--glow-color); }
}

/* Ripple button expand */
@keyframes ripple-expand {
  0% { transform: scale(0); opacity: 1; }
  100% { transform: scale(1); opacity: 0; }
}

/* Gradient border rotation */
@keyframes border-rotate {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Disintegration particle */
@keyframes disintegrate-particle {
  0% { opacity: 1; transform: translate(0, 0) rotate(0deg) scale(1); }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) rotate(var(--rot)) scale(0); }
}

/* Confetti burst */
@keyframes confetti-burst {
  0% { transform: translate(0, 0) rotate(0deg); opacity: 1; }
  100% { transform: translate(var(--confetti-tx), var(--confetti-ty)) rotate(var(--confetti-rot)); opacity: 0; }
}

/* Animated beam travel */
@keyframes beam-travel {
  0% { stroke-dashoffset: 2060; }
  100% { stroke-dashoffset: 0; }
}
@utility animate-beam-travel {
  animation: beam-travel 3s linear infinite;
}

/* Orbit animations */
@keyframes orbit-cw {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@keyframes orbit-ccw {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(-360deg); }
}
@utility animate-orbit-cw {
  animation: orbit-cw 20s linear infinite;
}
@utility animate-orbit-ccw {
  animation: orbit-ccw 20s linear infinite;
}

/* Smoke divider */
@keyframes smoke-drift {
  0% { transform: translateX(-200px) translateY(0px); }
  100% { transform: translateX(calc(100vw + 200px)) translateY(0px); }
}
@keyframes smoke-float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-8px); }
}

/* Glitch flicker */
@keyframes glitch-flicker {
  0% { opacity: 1; }
  50% { opacity: 0.6; }
  100% { opacity: 1; }
}

/* Retro grid scroll */
@keyframes retro-grid-scroll {
  0% { background-position: 0 0; }
  100% { background-position: 0 40px; }
}

/* Neon pulse glow */
@keyframes neon-pulse {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.15); }
}
.neon-pulse {
  animation: neon-pulse 3s ease-in-out infinite;
}

/* Pulse ring (pulse-button) */
@keyframes pulse-ring {
  0% { transform: scale(1); opacity: 0.6; }
  100% { transform: scale(1.6); opacity: 0; }
}

/* Orbit spin (orbit-animation) */
@keyframes orbit-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Glow text (glow-text) */
@keyframes glow-text {
  0% { text-shadow: 0 0 10px var(--glow-color), 0 0 20px var(--glow-color); }
  100% { text-shadow: 0 0 20px var(--glow-color), 0 0 40px var(--glow-color), 0 0 60px var(--glow-color); }
}
